import "server-only";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { gunzipSync } from "node:zlib";

/**
 * MOPH health-office registry (5-digit unit code → name and location), generated by
 * scripts/build-health-offices.py from health_office.xlsx. Loaded lazily once per server
 * instance (~41k units, 0.8 MB gzipped) and never sent to the browser in full.
 */
export interface HealthUnit {
  code: string;
  name: string;
  tambon: string;
  amphoe: string;
  province: string;
  active: boolean;
}

type Row = [name: string, tambon: string, amphoe: string, province: string, active: 0 | 1];

export const DIRECTORY_FILE = "src/content/health-offices.json.gz";

let directory: Record<string, Row> | null = null;

function load(): Record<string, Row> {
  directory ??= JSON.parse(
    gunzipSync(
      readFileSync(join(/*turbopackIgnore: true*/ process.cwd(), DIRECTORY_FILE)),
    ).toString("utf8"),
  ) as Record<string, Row>;
  return directory;
}

export const UNIT_CODE = /^\d{5}$/;

export function findUnit(code: string): HealthUnit | null {
  if (!UNIT_CODE.test(code)) return null;
  const row = load()[code];
  if (!row) return null;
  const [name, tambon, amphoe, province, active] = row;
  return { code, name, tambon, amphoe, province, active: active === 1 };
}
